script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { rp: null, done: {}, help: false, qr: false, why: false, toast: '', learn: true };
  }
  componentDidMount() { this._rpl = (e) => { if (e.detail.id === 'c1') this.setState({ done: { c1: { chip: e.detail.chip, text: e.detail.text } }, rp: null }); }; window.addEventListener('hb:reply', this._rpl); }
  componentWillUnmount() { window.removeEventListener('hb:reply', this._rpl); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o);
    const toast = (t) => { set({ toast: t }); clearTimeout(this._t); this._t = setTimeout(() => set({ toast: '' }), 3200); };
    /* ответ по задаче «Что дальше»: источник, чипы, итог */
    const RPD = { 'Фатима Аль-Мансури': 'Фатиме Аль-Мансури', 'Андреас Христоу': 'Андреасу Христоу' };
    const rpLc = (s) => s.charAt(0).toLowerCase() + s.slice(1);
    const rpWho = (c) => (c.mgr ? { src: c.mgr.n + ', локальный партнёр', to: RPD[c.mgr.n] || c.mgr.n, role: 'партнёр', pr: 'партнёру', gen: 'партнёра' } : { src: 'менеджер Housebook', to: 'менеджеру Housebook', role: 'менеджер', pr: 'менеджеру', gen: 'менеджера' });
    const rpVisit = (c) => /осмотр/.test((c.need && c.need.text) || '');
    const rpTail = (c, w) => (rpVisit(c) ? 'партнёр согласует осмотр' : /звонка партнёра/.test(c.need.text) ? 'партнёр позвонит клиенту в назначенное время' : /бюджет/.test(c.need.text) ? 'менеджер начнёт подбор объектов' : w.role + ' продолжит работу');
    const rpChipsOf = (c) => (rpVisit(c) ? ['Сможет приехать', 'Не сможет', 'Пока не знает'] : ['Сделано', 'Не получилось']);
    const rpMk = (c, d) => { const w = rpWho(c); return { calm: 'Ответ передан ' + w.to + '. Сейчас от Вас ничего не нужно: ' + rpTail(c, w) + ' и напишет, если что-то понадобится.', ev: { tone: 'sys', icon: 'send', title: (rpVisit(c) ? 'Вы передали ответ клиента: ' : 'Вы отметили задачу: ') + rpLc(d.chip), text: d.text || '', time: 'сейчас' } }; };
    const C1 = { id: 'c1', mgr: { n: 'Фатима Аль-Мансури' }, need: { text: 'Подтвердить клиенту время звонка партнёра' } };
    const dn1 = S.done.c1, rpWh = rpWho(C1), rpOn = !dn1 && !!S.rp;
    const nx = {
      tone: dn1 ? 'ok' : 'warn', warn: !dn1, ok: !!dn1, calm: dn1 ? rpMk(C1, dn1).calm : '', src: 'Просит: ' + rpWh.src,
      canReply: !dn1 && !rpOn, rpOpen: rpOn, rpQ: 'Как прошло',
      rpChips: rpChipsOf(C1).map((t) => ({ t: t, on: rpOn && S.rp.chip === t ? 'true' : 'false', pick: () => set({ rp: Object.assign({}, S.rp, { chip: t, err: false }) }) })),
      rpErrCls: rpOn && S.rp.err ? 'is-err' : '', rpText: rpOn ? S.rp.text : '', rpOnText: (e) => set({ rp: Object.assign({}, S.rp, { text: e.target.value }) }),
      rpLabel: 'Комментарий для ' + rpWh.gen, rpPh: 'Например: что ответил клиент и что важно знать',
      rpSendT: 'Отправить ' + rpWh.pr, rpToggle: () => set({ rp: { chip: '', text: '', err: false } }), rpCancel: () => set({ rp: null }),
      rpSend: () => { if (!S.rp || !S.rp.chip) { set({ rp: Object.assign({}, S.rp, { err: true }) }); return; } const d = { chip: S.rp.chip, text: (S.rp.text || '').trim() }; set({ done: { c1: d }, rp: null }); window.dispatchEvent(new CustomEvent('hb:reply', { detail: { id: 'c1', chip: d.chip, text: d.text } })); toast('Ответ передан ' + rpWh.pr); }
    };
    return {
      nx, ctaCls: rpOn ? 'btn--t' : 'btn--acc',
      help: S.help, toggleHelp: () => set({ help: !S.help }),
      qr: S.qr, openQr: () => set({ qr: true }), closeQr: () => set({ qr: false }), saveQr: () => { set({ qr: false }); toast('Картинка сохранена в загрузки'); },
      why: S.why, notWhy: !S.why, whyExp: S.why ? 'true' : 'false', whyBtn: S.why ? 'Свернуть' : 'Как это работает', toggleWhy: () => set({ why: !S.why }),
      copyLink: () => toast('Ссылка скопирована'),
      shareWa: () => toast('В кабинете откроется WhatsApp со ссылкой'),
      shareTg: () => toast('В кабинете откроется Telegram со ссылкой'),
      shareMl: () => toast('В кабинете откроется письмо со ссылкой'),
      asClient: () => toast('В кабинете откроется страница так, как её увидит клиент'),
      learn: S.learn, notLearn: !S.learn, hide: () => set({ learn: false }), show: () => set({ learn: true }),
      hasToast: !!S.toast, toast: S.toast
    };
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props);  }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.evNew = HB.events(); return v; }
}; })(Component);
